from collections import defaultdict
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """
    Choose between a constrained original column order and a constrained
    repetition-ranked global order using exact serialized Trie reuse.

    The algorithm never changes values, rows, columns, index labels, or shape.
    It only permutes existing cell positions within every row using one selected
    global order, while returning the corresponding source-column ordering.
    """

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional DataFrame argument for compatibility."""
        self.df = df

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """
        Return the longest common prefix of two strings.

        Equal strings and differing first characters are handled as cheap fast
        paths. Remaining cases use binary-search slice comparisons, keeping
        character comparison inside optimized string operations.
        """
        limit = min(len(left), len(right))
        if limit == 0:
            return 0
        if left == right:
            return limit
        if left[0] != right[0]:
            return 0

        low = 1
        high = limit

        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1

        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """
        Compute ideal character-Trie reuse for a multiset of serialized rows.

        Lexicographically adjacent strings contain all relevant shared-prefix
        relationships, so the adjacent LCP sum is the exact serial Trie reuse
        objective for the fixed collection of output strings.
        """
        if len(strings) < 2:
            return 0

        ordered = sorted(strings)
        total = 0
        previous = ordered[0]

        for current in ordered[1:]:
            if current == previous:
                total += len(current)
            elif current and previous and current[0] == previous[0]:
                total += cls._lcp(previous, current)
            previous = current

        return total

    @staticmethod
    def _serialize_global(text_values: np.ndarray, order: List[int]) -> List[str]:
        """
        Serialize every row under one shared column order.

        The input is already normalized exactly for scoring purposes: missing
        values are represented as empty strings and all other values as strings.
        """
        selected = text_values[:, order]
        return ["".join(row) for row in selected]

    @staticmethod
    def _dependency_edges(columns, one_way_dep):
        """
        Resolve requested precedence constraints into integer column edges.

        Exact labels are preferred. A unique substring match is retained for
        compatibility with callers that provide abbreviated historical labels.
        """
        exact = {}
        for index, name in enumerate(columns):
            if name not in exact:
                exact[name] = index

        def resolve(value):
            if value in exact:
                return exact[value]

            matches = [
                index
                for index, name in enumerate(columns)
                if str(value) in str(name)
            ]
            return matches[0] if len(matches) == 1 else None

        edges = []
        for pair in one_way_dep or []:
            if len(pair) != 2:
                continue

            left = resolve(pair[0])
            right = resolve(pair[1])

            if left is not None and right is not None and left != right:
                edges.append((left, right))

        return edges

    @staticmethod
    def _apply_dependencies(order, edges):
        """
        Stably topologically repair an order while retaining every column.

        Cyclic constraints are tolerated. Columns unresolved by the topological
        traversal are appended in their prior candidate-relative order.
        """
        if not edges:
            return list(order)

        position = {column: index for index, column in enumerate(order)}
        indegree = {column: 0 for column in order}
        children = defaultdict(list)

        for left, right in edges:
            if left in indegree and right in indegree:
                children[left].append(right)
                indegree[right] += 1

        available = [column for column in order if indegree[column] == 0]
        result = []

        while available:
            best_index = 0
            for index in range(1, len(available)):
                if position[available[index]] < position[available[best_index]]:
                    best_index = index

            current = available.pop(best_index)
            result.append(current)

            for child in children[current]:
                indegree[child] -= 1
                if indegree[child] == 0:
                    available.append(child)

        if len(result) != len(order):
            emitted = set(result)
            result.extend(column for column in order if column not in emitted)

        return result

    @staticmethod
    def _merge_blocks(order, col_merge, columns):
        """
        Keep requested merge groups contiguous without changing any cell values.

        Members of a merge group retain their candidate-order-relative ranking.
        Overlapping groups are handled deterministically by assigning a column
        only to the first group in which it appears.
        """
        if not col_merge:
            return list(order)

        name_to_index = {}
        for index, name in enumerate(columns):
            if name not in name_to_index:
                name_to_index[name] = index

        member_group = {}
        groups = {}

        for group_id, group in enumerate(col_merge):
            members = []

            for name in group:
                column = name_to_index.get(name)
                if column is not None and column not in member_group:
                    member_group[column] = group_id
                    members.append(column)

            if members:
                groups[group_id] = members

        if not groups:
            return list(order)

        rank = {column: index for index, column in enumerate(order)}
        emitted = set()
        merged = []

        for column in order:
            group_id = member_group.get(column)

            if group_id is None:
                merged.append(column)
            elif group_id not in emitted:
                emitted.add(group_id)
                merged.extend(sorted(groups[group_id], key=rank.get))

        return merged

    @staticmethod
    def _repetition_scores(text_values: np.ndarray) -> np.ndarray:
        """
        Compute global length-weighted exact-value repetition scores.

        Each column is scored as:
            sum(len(value) * count(value) * (count(value) - 1))

        This provides a cheap ordering hypothesis that favors long repeated
        serialized prefixes. Final selection is still based on exact full-row
        Trie reuse rather than this approximate field statistic.
        """
        _, n_cols = text_values.shape
        scores = np.zeros(n_cols, dtype=np.int64)

        for column in range(n_cols):
            codes, uniques = pd.factorize(text_values[:, column], sort=False)
            codes = np.asarray(codes, dtype=np.int64)

            counts = np.bincount(codes, minlength=len(uniques)).astype(np.int64)
            lengths = np.fromiter(
                (len(value) for value in uniques),
                dtype=np.int64,
                count=len(uniques),
            )

            scores[column] = int(np.sum(lengths * counts * (counts - 1)))

        return scores

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge: List[List[str]] = [],
        one_way_dep: List[Tuple[str, str]] = [],
        distinct_value_threshold: float = 0.8,
        parallel: bool = True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """
        Return the better of original and repetition-ranked global orders.

        Candidate evaluation uses evaluator-compatible normalized serialized
        values, but returned data is copied only from the original object
        matrix. Thus missing values and mixed source types remain unchanged.
        """
        n_rows, n_cols = df.shape

        if n_rows == 0 or n_cols == 0:
            return df.copy(), [[] for _ in range(n_rows)]

        text_values = df.fillna("").astype(str).to_numpy(dtype=object, copy=True)
        raw_values = df.to_numpy(dtype=object, copy=True)
        columns = list(df.columns)

        dependency_edges = self._dependency_edges(columns, one_way_dep)
        repetition_scores = self._repetition_scores(text_values)

        original_order = list(range(n_cols))
        frequency_order = sorted(
            range(n_cols),
            key=lambda column: (-int(repetition_scores[column]), column),
        )

        original_order = self._merge_blocks(
            original_order,
            col_merge,
            columns,
        )
        frequency_order = self._merge_blocks(
            frequency_order,
            col_merge,
            columns,
        )

        original_order = self._apply_dependencies(
            original_order,
            dependency_edges,
        )
        frequency_order = self._apply_dependencies(
            frequency_order,
            dependency_edges,
        )

        original_score = self._trie_score(
            self._serialize_global(text_values, original_order)
        )
        frequency_score = self._trie_score(
            self._serialize_global(text_values, frequency_order)
        )

        if frequency_score > original_score:
            selected_order = frequency_order
        else:
            selected_order = original_order

        output = raw_values[:, selected_order].copy()

        reordered_df = pd.DataFrame(
            output,
            index=df.index.copy(),
            columns=df.columns.copy(),
            dtype=object,
        )

        column_ordering = [columns[column] for column in selected_order]

        return reordered_df, [list(column_ordering) for _ in range(n_rows)]


